import {useEffect,useState} from 'react';
import {X,Download,History,Eye,RotateCcw} from 'lucide-react';
import {api} from '../app/api';
import {ResizeHandle} from './ResizeHandle';

/** Generated files keep their identity even when a preview conversion fails. */
export function FilePreviewPanel({fileId,files,onSelect,conversationId,projectId,onClose,onError}:{fileId:string;files:any[];onSelect:(id:string)=>void;conversationId:string;projectId?:string;onClose:()=>void;onError:(message:string)=>void}){
 const [file,setFile]=useState<any>();const [versions,setVersions]=useState<any[]>([]);const [tab,setTab]=useState('preview');const [comparison,setComparison]=useState<any>();const [selected,setSelected]=useState(0);const [busy,setBusy]=useState(false);const [width,setWidth]=useState<number>();
 useEffect(()=>{let active=true;let loading=false;setFile(undefined);setVersions([]);setComparison(undefined);setSelected(0);const load=async()=>{if(loading)return;loading=true;try{const info=await api('/files/'+encodeURIComponent(fileId)+'/info');if(!active)return;setFile(info);const history=await api('/files/'+encodeURIComponent(fileId)+'/versions');if(active)setVersions(history.revisions??[]);}catch(error){if(active)onError((error as Error).message);}finally{loading=false;}};void load();const timer=setInterval(()=>void load(),2500);return()=>{active=false;clearInterval(timer);};},[fileId]);
 const [source,setSource]=useState('');useEffect(()=>{let active=true;setSource('');if(tab==='source')api('/files/'+encodeURIComponent(fileId)+'/source').then(value=>{if(active)setSource(value.text);}).catch(error=>{if(active)onError(error.message);});return()=>{active=false;};},[fileId,file?.contentHash,tab]);
 const compare=async(revision:number)=>{setSelected(revision);setComparison(undefined);try{const result=await api('/files/'+encodeURIComponent(fileId)+'/compare?before='+revision+'&after='+file.revision);setComparison(result);}catch(error){onError((error as Error).message);}};
 const revert=async()=>{if(!file||!selected||busy)return;setBusy(true);try{const result=await api('/tools/call',{method:'POST',body:JSON.stringify({name:'files_revert',conversationId,projectId,arguments:{file_id:fileId,revision:selected,expected_hash:file.contentHash}})});if(result.status!=='succeeded')throw new Error(result.error?.message??'Revert failed');setFile(await api('/files/'+encodeURIComponent(fileId)+'/info'));setComparison(undefined);setSelected(0);}catch(error){onError((error as Error).message);}finally{setBusy(false);}};
 return <aside className="artifact-panel" style={{width}} aria-label="Generated file preview"><ResizeHandle width={width} onResize={setWidth}/><div className="panel-heading"><div><strong>{file?.name??'Opening file…'}</strong><small>{file?.revision?'Revision '+file.revision:'Generated file'}</small></div><button className="icon-button" aria-label="Close file preview" onClick={onClose}><X size={18}/></button></div><div role="tablist" aria-label="Generated files" style={{display:'flex',overflowX:'auto',gap:6,padding:8}}>{files.map(item=><button role="tab" aria-selected={item.id===fileId} key={item.id} onClick={()=>onSelect(item.id)}>{item.name??'File'}</button>)}</div><div className="artifact-toolbar"><button onClick={()=>setTab('preview')}><Eye size={14}/>Preview</button><button onClick={()=>setTab('source')}>Source</button><button onClick={()=>setTab('history')}><History size={14}/>Changes</button>{file&&<a href={file.url} download aria-label="Download file"><Download size={16}/></a>}</div>{file?.revisionError&&<p role="status">{file.revisionError}</p>}{file?.previewStale&&<p role="status">The source changed after this preview was rendered. Download the current source to view its latest contents.</p>}<div className="artifact-content" style={{overflow:'auto'}}>{tab==='source'?<pre style={{padding:16,whiteSpace:'pre-wrap'}}>{source}</pre>:tab==='preview'?file?.previewable&&!file.previewStale?<iframe key={file.previewUrl} title={file.name} src={file.previewUrl} sandbox="allow-scripts allow-downloads"/>:<p style={{padding:20}}>The file is saved. A current preview is unavailable for this format.</p>:<div style={{padding:16}}><label>Compare with current revision <select value={selected} onChange={event=>void compare(Number(event.target.value))}><option value={0} disabled>Choose a revision</option>{versions.map(row=><option value={row.revision} key={row.revision}>v{row.revision} · {row.origin}</option>)}</select></label>{comparison&&<><p>{comparison.identical?'These revisions are identical.':'The file changed between these revisions.'}</p>{comparison.text?<div style={{display:'grid',gap:12}}><strong>Previous source</strong><pre style={{whiteSpace:'pre-wrap'}}>{comparison.textBefore}</pre><strong>Current source</strong><pre style={{whiteSpace:'pre-wrap'}}>{comparison.textAfter}</pre></div>:<p>Binary changes are recorded by hash and size.</p>}{selected!==file?.revision&&<button disabled={busy} onClick={()=>void revert()}><RotateCcw size={14}/>{busy?'Restoring…':'Restore this revision'}</button>}</>}</div>}</div></aside>;
}
